"""Reproduces the CUDA English BIP39 word table from python-mnemonic."""

from pathlib import Path

from mnemonic import Mnemonic


def generate_table():
	"""Returns the standard 2048-word English table as null-terminated CUDA strings."""

	words = Mnemonic('english').wordlist
	if len(words) != 2048 or max(map(len, words)) > 8:
		raise ValueError('unexpected English BIP39 word list')
	lines = [
		'// Generated by scripts/generate_bip39_words.py from python-mnemonic (MIT); see CUDA_NOTICES.md.',
		'__constant__ char BIP39_WORDS[2048][9] = {'
	]
	for offset in range(0, len(words), 8):
		lines.append('\t' + ', '.join(f'"{word}"' for word in words[offset:offset + 8]) + ',')
	lines.append('};')
	return '\n'.join(lines) + '\n'


if '__main__' == __name__:
	(Path(__file__).parents[1] / 'vanity' / 'bip39_words.cuh').write_text(generate_table(), encoding='utf8')
